// This file is generated by AI.

//! Live2D 的 motion/expression 状态必须在时间线编译期正确延续：
//! - 只改表情的语句不能清掉当前 motion，也不能把动作倒回第一帧；
//! - 没写 `-expression` 的动作语句要沿用之前的表情覆盖。

use std::fs;
use std::path::Path;

use webgal_video_export::api::{ExportOptions, build_plan};

fn write(root: &Path, relative: &str, text: &str) {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, text).expect("write fixture");
}

#[test]
fn expression_and_motion_state_survive_later_commands() {
    let directory = tempfile::tempdir().expect("temp dir");
    let root = directory.path();
    write(root, "game/config.txt", "Game_name:Pose;\n");
    write(root, "game/figure/test/test.model3.json", "{}");
    write(
        root,
        "game/scene/start.txt",
        "\
changeFigure:test/test.model3.json -left -id=hero -expression=sad01 -next;
wait:1000;
changeFigure:test/test.model3.json -left -id=hero -motion=idle01 -next;
wait:1000;
changeFigure:test/test.model3.json -left -id=hero -motion=serious01 -next;
wait:1000;
changeFigure:test/test.model3.json -left -id=hero -motion=idle01 -next;
wait:1000;
changeFigure:test/test.model3.json -left -id=hero -expression=smile01 -next;
wait:1000;
changeFigure:test/test.model3.json -left -id=hero -motion=serious01 -next;
wait:1000;
end;
",
    );

    let plan = build_plan(&ExportOptions::new(root)).expect("build plan");
    let poses = &plan.figures[0].poses;
    assert_eq!(poses.len(), 6, "每次 motion/expression 语句都应有姿态事件");

    assert_eq!(poses[0].expression.as_deref(), Some("sad01"));
    assert_eq!(poses[0].motion, None);
    assert_eq!(poses[0].motion_start_us, 0);

    // 后续 motion 语句没有重复写表情，表情覆盖必须继续生效。
    assert_eq!(poses[1].expression.as_deref(), Some("sad01"));
    assert_eq!(poses[1].motion.as_deref(), Some("idle01"));
    assert_eq!(poses[1].motion_start_us, 1_000_000);

    assert_eq!(poses[2].expression.as_deref(), Some("sad01"));
    assert_eq!(poses[2].motion.as_deref(), Some("serious01"));
    assert_eq!(poses[2].motion_start_us, 2_000_000);

    // 再次显式 `-motion` 时重新起播；表情覆盖仍然保留。
    assert_eq!(poses[3].expression.as_deref(), Some("sad01"));
    assert_eq!(poses[3].motion.as_deref(), Some("idle01"));
    assert_eq!(poses[3].motion_start_us, 3_000_000);

    // 只改表情时沿用 idle01 的起播时间，动作不会重头播放。
    assert_eq!(poses[4].expression.as_deref(), Some("smile01"));
    assert_eq!(poses[4].motion.as_deref(), Some("idle01"));
    assert_eq!(poses[4].motion_start_us, 3_000_000);

    assert_eq!(poses[5].expression.as_deref(), Some("smile01"));
    assert_eq!(poses[5].motion.as_deref(), Some("serious01"));
    assert_eq!(poses[5].motion_start_us, 5_000_000);
}
